DROP TABLE IF EXISTS `standard_pedigree`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `standard_pedigree` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `std_code` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '国标号（本标准标准号）',
  `latest_std_code` mediumtext COLLATE utf8mb4_unicode_ci COMMENT '国标最新版本号（可能多条，顿号「、」拼接）',
  `ped_id` mediumtext COLLATE utf8mb4_unicode_ci COMMENT '谱系号（可能多条，英文逗号拼接）',
  `part_chain` mediumtext COLLATE utf8mb4_unicode_ci COMMENT '谱系链（完整表达式）',
  PRIMARY KEY (`id`),
  KEY `idx_standard_pedigree_std_code` (`std_code`),
  KEY `idx_standard_pedigree_ped_id` (`ped_id`(127))
) ENGINE=InnoDB AUTO_INCREMENT=77240 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='谱系表';
